    private readonly CancellationTokenSource _life=new();
    private readonly StackPanel _page=new(){Spacing=24,Padding=new Thickness(32,35,32,32),MaxWidth=924,HorizontalAlignment=HorizontalAlignment.Stretch};
    private List<JsonNode> _sessions=[];
    private bool _loading=true;
    private string? _error;
    private static readonly FontFamily Sans=new("ms-appx:///Assets/Library/LibrarySans-Regular.otf#DrawOffer Library Sans"),Serif=new("ms-appx:///Assets/Library/LibrarySerif-SemiBold.ttf#DrawOffer Library Serif");
    private static SolidColorBrush Brush(uint value)=>new(ColorHelper.FromArgb(255,(byte)(value>>16),(byte)(value>>8),(byte)value));
    private static TextBlock Text(string text,double size=13,uint color=0x1D1D1B,bool serif=false)=>new(){Text=text,FontSize=size,FontFamily=serif?Serif:Sans,Foreground=Brush(color),TextWrapping=TextWrapping.Wrap};
